using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.TwistedGround;

internal sealed class NativeAffineTransportDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/VertexAlgebra/TwistedGround/NativeAffineTransport.";
    private static readonly LibraryNoteRef Background = LibraryNoteRef.Create("D5/L/VertexAlgebra/flm1988monster");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native affine Taylor comparison and linear transport", H("Native affine Taylor comparison and linear transport"),
        Blocks(
            Paragraph(Text("Finite complex polynomial identities for arbitrary finite index types, including empty types, rectangular, zero and singular substitutions. The native affine coefficient retains its original auxiliary-coordinate definition. Covariance is U A transpose(U), with ordinary transpose, and mean is U mu. The original charged-row application is in OriginalSourceInverseCoefficient; no full sewing or physical realization is asserted.")),
            Describe.Lean(DescribeId.Create("original-source-inverse-linearsubstitution"), DeclarationHandle.Create(Prefix + "linearSubstitution"), H("Finite linear substitution"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For arbitrary finite types I and J, including empty types, linearSubstitution(U) sends X_j to the sum of U[i,j] X_i. Matrices are complex and may be rectangular, zero or singular."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-inverse-transportcovariance"), DeclarationHandle.Create(Prefix + "transportCovariance"), H("Ordinary covariance transport"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("transportCovariance(U,A) is U A transpose(U), with ordinary transpose and no complex conjugation."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-inverse-transportmean"), DeclarationHandle.Create(Prefix + "transportMean"), H("Affine mean transport"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("transportMean(U,mu) is U mu."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-inverse-sourceblock"), DeclarationHandle.Create(Prefix + "sourceBlock"), H("Fix the external coordinates"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("sourceBlock(U) is block diagonal with U on source coordinates and identity on all external coordinates."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("original-source-inverse-affinecoefficient-linear-substitution"), DeclarationHandle.Create(Prefix + "affineCoefficient_linear_substitution"), H("Native affine coefficient covariance"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I and J, U:I by J, symmetric complex A, arbitrary complex mean mu, target occupation d and natural N with degree(d) at most N, the sum over all source occupations e of total degree at most N of affineCoefficient(A,mu,e) times the d coefficient of linearSubstitution(U,X^e) equals affineCoefficient(U A transpose(U),U mu,d). The native auxiliary-coordinate coefficient definition is retained. The native_affine_eq_taylor comparison proves its equality with ordinary Taylor coefficients from the native moment recurrence, including zero degree and empty types."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-expcut"), DeclarationHandle.Create(Prefix + "expCut"), H("Finite exponential polynomial"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For any finite type I, complex polynomial p and natural N, expCut(p,N) is the sum for k from zero through N of p^k divided by k factorial. The zero and empty-type cases are included."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-affine-transport-affineexponent"), DeclarationHandle.Create(Prefix + "affineExponent"), H("Quadratic and linear exponent"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I, complex square A and mean mu, affineExponent(A,mu) is quadratic(A) plus the sum over i of mu(i) X_i, with the existing half-quadratic convention. Symmetry is required by the comparison theorems, not by this definition."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-affine-transport-taylorcoefficient"), DeclarationHandle.Create(Prefix + "taylorCoefficient"), H("Degree-bounded Taylor coefficient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I, complex A, mean mu and occupation d, taylorCoefficient(A,mu,d) extracts coefficient d from expCut(affineExponent(A,mu),degree(d))."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-affine-transport-affineexponent-constant"), DeclarationHandle.Create(Prefix + "affineExponent_constant"), H("Zero affine exponent constant"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("The actual affine exponent has zero constant coefficient, including empty index types. External ordinary extraction consumes this exact original polynomial fact."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-pderiv-expcut"), DeclarationHandle.Create(Prefix + "pderiv_expCut"), H("Finite exponential polynomial derivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("Differentiating the finite exponential polynomial of order n+1 yields the derivative of its exponent times the finite exponential polynomial of order n. The ordinary factorial ratios are exact."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-taylorcoefficient-cut"), DeclarationHandle.Create(Prefix + "taylorCoefficient_cut"), H("Stable Taylor cutoff"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I, complex A, arbitrary mean mu, occupation d and natural N with degree(d) at most N, taylorCoefficient(A,mu,d) equals the d coefficient of expCut(affineExponent(A,mu),N). The zero constant term forces all powers above degree(d) to vanish at d. The original-row proof consumes this equality with N=n+degree(betaR)+degree(gammaR)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-native-affine-eq-taylor"), DeclarationHandle.Create(Prefix + "native_affine_eq_taylor"), H("Native recurrence equals Taylor coefficients"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I, symmetric complex A, arbitrary mean mu and occupation d, the original affineCoefficient(A,mu,d) equals taylorCoefficient(A,mu,d). Strong occupation induction compares the native affine moment recurrence with the factorial-normalized derivative recurrence. It includes d=0 and empty I, and is used by transport and the original-row readout."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-externalsection"), DeclarationHandle.Create(Prefix + "externalSection"), H("Extract fixed external occupations"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For finite I and J, polynomial p on I plus J and external occupation h on J, externalSection(p,h) is the polynomial on I obtained by extracting h through the swapped sum-ring equivalence. No evaluation of external variables at one is performed."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-affine-transport-externalsection-coeff"), DeclarationHandle.Create(Prefix + "externalSection_coeff"), H("Joint occupation coefficient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I and J, complex polynomial p on I plus J, h on J and d on I, the d coefficient of externalSection(p,h) equals the coefficient of p at d.sumElim(h)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-externalsection-native"), DeclarationHandle.Create(Prefix + "externalSection_native"), H("Native transport with external occupations"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For every finite I and J, complex square U on I, symmetric complex A on I plus J, arbitrary mean mu, occupations d and h and N at least degree(d.sumElim(h)), the d coefficient of linearSubstitution(U,externalSection(expCut(affineExponent(A,mu),N),h)) equals affineCoefficient(transportCovariance(sourceBlock(U),A),transportMean(sourceBlock(U),mu),d.sumElim(h)). The block fixes every external coordinate and ordinary transpose is used. This supplies the original-row proof with both external occupations intact."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-affine-transport-covariance-symm"), DeclarationHandle.Create(Prefix + "transportCovariance_symm"), H("Ordinary symmetry under transport"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Background), Blocks(Paragraph(Text("For arbitrary finite types, a complex rectangular substitution transports a symmetric covariance to a symmetric covariance by ordinary transpose. No positivity, invertibility or nonempty-type hypothesis is required."))), DescribeRole.Theorem),
            Paragraph(Text("The native moment recurrence is compared with the finite exponential polynomial by strong occupation induction. Total target degree controls the Taylor cutoff. Gaussian polynomial calculus is classical, and this reusable transport makes no literature novelty claim."))), []));
}
